namespace ghidra.graph.visualization.mouse;



using org.jungrapht.visualization.control;

using ghidra.graph.visualization;
using ghidra.service.graph;
using ghidra.service.graph;

/**
 * Pluggable graph mouse for jungrapht
 */
public class JgtGraphMouse : DefaultGraphMouse<AttributedVertex, AttributedEdge> {

	private DefaultGraphDisplay graphDisplay;
	private bool allowEdgeSelection;

	// TODO we should not need the graph display for any mouse plugins, but the API is net yet
	//      robust enough to communicate fully without it
	public JgtGraphMouse(DefaultGraphDisplay graphDisplay, bool allowEdgeSelection) : base(DefaultGraphMouse.builder())
    {
		this.graphDisplay = graphDisplay;
		this.allowEdgeSelection = allowEdgeSelection;
	}

	/* @SuppressWarnings("rawtypes") */
	/* @Override */
	public void loadPlugins() {

		//
		// Note: the order of these additions matters, as an event will flow to each plugin until
		//       it is handled.
		//

		// edge 
		add(new(InputEvent.BUTTON1_DOWN_MASK));

		add(new(InputEvent.BUTTON1_DOWN_MASK, graphDisplay));

		//
		// JUNGRAPHT CHANGE 1,2
		//
		// Note: this code can go away when we can turn off the picking square
		add(allowEdgeSelection ? new SelectingGraphMousePlugin()
				: new());
		// add(new SelectingGraphMousePlugin<>());

		add(new());

		// the grab/pan feature
		add(TranslatingGraphMousePlugin.builder()
				.translatingMask(InputEvent.BUTTON1_DOWN_MASK)
				.build());

		// scaling

		// allow y-axis scaling using Shift.  The default is Alt, which doesn't work on some OSes.
		ScalingGraphMousePlugin.Builder builder =
			ScalingGraphMousePlugin
					.builder()
					.yAxisScalingMask(Modifiers.masks.get("SHIFT"));
		ScalingGraphMousePlugin scaler = new ScalingGraphMousePlugin(builder);
		add(scaler);

		// cursor cleanup
		add(new());

		setPluginsLoaded();
	}

	public bool allowsEdgeSelection() {
		return allowEdgeSelection;
	}

}
